-- Aurora canvas study: every query behind the published page.
-- Generated by canvas_study_update.py; edit the generator, not this file.
-- Window: 2026-03-07 <= t < 2026-06-15; thought-based figures from 2026-03-21.
-- Excluded models: claude-opus-4.6.
-- MySQL 8. Read-only: every statement is a SELECT.

-- [totals] Section 6 (O1) totals and the abstract
SELECT (SELECT COUNT(*) FROM sessions WHERE started_at >= '2026-03-07' AND started_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6')) AS sessions, (SELECT COUNT(*) FROM sessions WHERE started_at >= '2026-03-07' AND started_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') AND painting_title IS NOT NULL AND painting_title != '' AND painting_title NOT LIKE '%rotation swap%' AND painting_title NOT LIKE '%in progress%') AS titled, (SELECT COUNT(DISTINCT model) FROM sessions WHERE started_at >= '2026-03-07' AND started_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6')) AS models, (SELECT COUNT(*) FROM thoughts WHERE captured_at >= '2026-03-07' AND captured_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6')) AS thoughts_all, (SELECT COUNT(*) FROM thoughts WHERE captured_at >= '2026-03-21' AND captured_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6')) AS thoughts_t0, (SELECT COUNT(*) FROM dreams WHERE dreamed_at >= '2026-03-07' AND dreamed_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6')) AS dreams, (SELECT COUNT(*) FROM reflections WHERE reflected_at >= '2026-03-07' AND reflected_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6')) AS reflections, (SELECT COUNT(*) FROM chats WHERE chatted_at >= '2026-03-07' AND chatted_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6')) AS chats, (SELECT COUNT(*) FROM sounds WHERE created_at >= '2026-03-07' AND created_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6')) AS sound_rows, (SELECT SUM(CHAR_LENGTH(chars)) FROM sounds WHERE created_at >= '2026-03-07' AND created_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6')) AS sound_chars;

-- [months] Section 6 (O1) monthly table
SELECT DATE_FORMAT(started_at, '%Y-%m') AS m, COUNT(*) AS sessions, COUNT(DISTINCT DATE(started_at)) AS active_days, MIN(DATE(started_at)) AS first_day, MAX(DATE(started_at)) AS last_day, COUNT(DISTINCT model) AS models FROM sessions WHERE started_at >= '2026-03-07' AND started_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') GROUP BY m ORDER BY m;

-- [end_types] Section 3 (how sessions end) and Section 6 (O2)
SELECT CASE WHEN painting_title IS NULL OR painting_title = '' THEN 'no_title' WHEN painting_title LIKE '%rotation swap%' THEN 'rotation_swap' WHEN painting_title LIKE '%in progress%' THEN 'continued' WHEN total_steps = 0 THEN 'saved_at_slot_end' ELSE 'self_saved' END AS end_type, COUNT(*) AS n, SUM(canvas_coverage = 0) AS zero_coverage FROM sessions WHERE started_at >= '2026-03-07' AND started_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') GROUP BY end_type ORDER BY n DESC;

-- [weeks] Chart A: sessions per week by length band
SELECT MIN(DATE(started_at)) AS week_from, COUNT(*) AS n, SUM(TIMESTAMPDIFF(MINUTE, started_at, ended_at) < 5) AS lt5, SUM(TIMESTAMPDIFF(MINUTE, started_at, ended_at) BETWEEN 5 AND 35) AS m5_35, SUM(TIMESTAMPDIFF(MINUTE, started_at, ended_at) BETWEEN 36 AND 70) AS m36_70, SUM(TIMESTAMPDIFF(MINUTE, started_at, ended_at) > 70) AS gt70, SUM(ended_at IS NULL) AS no_end FROM sessions WHERE started_at >= '2026-03-07' AND started_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') GROUP BY YEARWEEK(started_at, 3) ORDER BY week_from;

-- [dream_months] Chart B and Limitations L1: keyword rates of rest-phase output by month
SELECT DATE_FORMAT(dreamed_at, '%Y-%m') AS m, COUNT(*) AS n, ROUND(100 * AVG(REGEXP_LIKE(content, '\\b(paint|painting|canvas|colou?r|brush|art|artist|artistic|creat|draw|palette|stroke|hue|pigment)', 'i')), 1) AS art_pct, ROUND(100 * AVG(REGEXP_LIKE(content, '\\b(paint|canvas|colou?r|shape|feeling)', 'i')), 1) AS prompt_word_pct, ROUND(100 * AVG(REGEXP_LIKE(content, '\\b(paint|painting|canvas|colou?r|brush|art|artist|artistic|creat|draw|palette|stroke|hue|pigment)', 'i') AND NOT REGEXP_LIKE(content, '\\b(paint|canvas|colou?r|shape|feeling)', 'i')), 1) AS art_only_pct FROM dreams WHERE dreamed_at >= '2026-03-07' AND dreamed_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') GROUP BY m ORDER BY m;

-- [dream_periods] Section 3 (rest structure) and Section 6 (O7)
SELECT CASE WHEN dreamed_at < '2026-04-15' THEN 'before' ELSE 'after' END AS period, COUNT(*) AS dreams, COUNT(DISTINCT session_id) AS sessions_with_output FROM dreams WHERE dreamed_at >= '2026-03-07' AND dreamed_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') GROUP BY period ORDER BY period DESC;

-- [dream_max] Section 3: most rest-phase outputs logged in one session
SELECT MAX(k) AS max_in_one_session FROM (SELECT COUNT(*) AS k FROM dreams WHERE dreamed_at >= '2026-03-07' AND dreamed_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') AND session_id IS NOT NULL GROUP BY session_id) x;

-- [emotion_summary] Section 6 (O4)
SELECT COUNT(*) AS thoughts, SUM(emotion IS NOT NULL AND emotion <> 'base') AS with_word, COUNT(DISTINCT CASE WHEN emotion IS NOT NULL AND emotion <> 'base' THEN emotion END) AS distinct_words FROM thoughts WHERE captured_at >= '2026-03-21' AND captured_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6');

-- [emotion_once] Section 6 (O4): words that occur in one session only
SELECT COUNT(*) AS words_in_one_session FROM (SELECT emotion FROM thoughts WHERE captured_at >= '2026-03-21' AND captured_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') AND emotion IS NOT NULL AND emotion <> 'base' GROUP BY emotion HAVING COUNT(DISTINCT session_id) = 1) x;

-- [emotion_top] Section 6 (O4): most frequent emotion words
SELECT emotion, COUNT(*) AS n FROM thoughts WHERE captured_at >= '2026-03-21' AND captured_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') AND emotion IS NOT NULL AND emotion <> 'base' GROUP BY emotion ORDER BY n DESC LIMIT 10;

-- [emotion_confirmed] Methods: emotion rows that match a model's own text
SELECT COUNT(*) AS rows_all, SUM(t.id IS NOT NULL) AS matched FROM emotions e LEFT JOIN thoughts t ON t.session_id = e.session_id AND t.model = e.model AND t.step = e.step AND t.emotion = e.emotion WHERE e.emotion <> 'base' AND e.occurred_at >= '2026-03-21' AND e.occurred_at < '2026-06-15' AND e.model NOT IN ('claude-opus-4.6');

-- [thought_key] Limitations L4: days on which thought rows equal distinct (model, step)
SELECT DATE(captured_at) AS d, COUNT(*) AS rows_n, COUNT(DISTINCT model, step) AS distinct_model_step FROM thoughts WHERE captured_at >= '2026-03-07' AND captured_at < '2026-03-28' AND model NOT IN ('claude-opus-4.6') GROUP BY d ORDER BY d;

-- [thoughts_before] Limitations L4: thought rows dated before the key change
SELECT COUNT(*) AS n FROM thoughts WHERE captured_at >= '2026-03-07' AND captured_at < '2026-03-21' AND model NOT IN ('claude-opus-4.6');

-- [reflection_types] Section 6 (O6)
SELECT question_key, COUNT(*) AS n, MIN(DATE(reflected_at)) AS first_day, MAX(DATE(reflected_at)) AS last_day FROM reflections WHERE reflected_at >= '2026-03-07' AND reflected_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') GROUP BY question_key ORDER BY n DESC;

-- [reflection_temp] Section 6 (O6) and timeline: sampling temperature of reflections
SELECT temperature, COUNT(*) AS n, MIN(DATE(reflected_at)) AS first_day, MAX(DATE(reflected_at)) AS last_day FROM reflections WHERE reflected_at >= '2026-03-07' AND reflected_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') GROUP BY temperature ORDER BY first_day;

-- [titles] Section 6 (O5): titles (cleaned in Python by clean_title, then matched across models)
SELECT model, painting_title FROM sessions WHERE started_at >= '2026-03-07' AND started_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6') AND painting_title IS NOT NULL AND painting_title != '' AND painting_title NOT LIKE '%rotation swap%' AND painting_title NOT LIKE '%in progress%';

-- [roster] Section 3 model table
SELECT s.model, COUNT(*) AS sessions, SUM(painting_title IS NOT NULL AND painting_title != '' AND painting_title NOT LIKE '%rotation swap%' AND painting_title NOT LIKE '%in progress%') AS titled, MIN(DATE(s.started_at)) AS first_day, (SELECT COUNT(*) FROM dreams d WHERE d.model = s.model COLLATE utf8mb4_0900_ai_ci AND d.dreamed_at >= '2026-03-07' AND d.dreamed_at < '2026-06-15') AS dreams, (SELECT COUNT(*) FROM reflections r WHERE r.model = s.model COLLATE utf8mb4_0900_ai_ci AND r.reflected_at >= '2026-03-07' AND r.reflected_at < '2026-06-15') AS reflections FROM sessions s WHERE s.started_at >= '2026-03-07' AND s.started_at < '2026-06-15' AND s.model NOT IN ('claude-opus-4.6') GROUP BY s.model ORDER BY first_day, s.model;

-- [claude] Section 3: Claude Sonnet 4.6 sessions
SELECT COUNT(*) AS n, MIN(DATE(started_at)) AS first_day, SUM(TIMESTAMPDIFF(MINUTE, started_at, ended_at) >= 60) AS ge_60_min, SUM((CASE WHEN painting_title IS NULL OR painting_title = '' THEN 'no_title' WHEN painting_title LIKE '%rotation swap%' THEN 'rotation_swap' WHEN painting_title LIKE '%in progress%' THEN 'continued' WHEN total_steps = 0 THEN 'saved_at_slot_end' ELSE 'self_saved' END) = 'self_saved') AS self_saved FROM sessions WHERE model = 'claude-sonnet-4-6' AND started_at >= '2026-03-07' AND started_at < '2026-06-15';

-- [integrity] Limitations L10 (whole database)
SELECT (SELECT COUNT(*) FROM sessions) AS session_rows, (SELECT MAX(id) FROM sessions) AS max_session_id, (SELECT COUNT(*) FROM thoughts WHERE session_id IS NULL) AS orphan_thoughts, (SELECT COUNT(*) FROM emotions WHERE session_id IS NULL) AS orphan_emotions, (SELECT COUNT(*) FROM dreams WHERE session_id IS NULL) AS orphan_dreams;

-- [later_runs] Section 8: runs after the window and before the separate experiment
SELECT model, DATE(started_at) AS d, COUNT(*) AS sessions, SUM(painting_title IS NOT NULL AND painting_title != '' AND painting_title NOT LIKE '%rotation swap%' AND painting_title NOT LIKE '%in progress%') AS titled, MAX(TIMESTAMPDIFF(MINUTE, started_at, ended_at)) AS longest_min FROM sessions WHERE started_at >= '2026-06-15' AND started_at < '2026-10-16' GROUP BY model, d ORDER BY d;

-- [excluded] Methods: rows excluded as hand-composed
SELECT COUNT(*) AS sessions, MIN(DATE(started_at)) AS first_day, MAX(DATE(started_at)) AS last_day FROM sessions WHERE NOT (model NOT IN ('claude-opus-4.6')) AND started_at >= '2026-03-07' AND started_at < '2026-06-15';

-- [figures] Figures 1-3: median-coverage self-saved, blank-start session of each figure model
WITH s AS (SELECT id, model, started_at, total_steps, canvas_coverage, painting_title, CASE WHEN painting_title IS NULL OR painting_title = '' THEN 'no_title' WHEN painting_title LIKE '%rotation swap%' THEN 'rotation_swap' WHEN painting_title LIKE '%in progress%' THEN 'continued' WHEN total_steps = 0 THEN 'saved_at_slot_end' ELSE 'self_saved' END AS end_type FROM sessions WHERE started_at >= '2026-03-07' AND started_at < '2026-06-15' AND model NOT IN ('claude-opus-4.6')), s2 AS (SELECT s.*, LAG(end_type) OVER (PARTITION BY model ORDER BY started_at, id) AS prev_end FROM s), c AS (SELECT * FROM s2 WHERE end_type = 'self_saved' AND (prev_end IS NULL OR prev_end IN ('self_saved', 'saved_at_slot_end')) AND model IN ('deepseek-r1-8b', 'mistral', 'qwen')), r AS (SELECT c.*, ROW_NUMBER() OVER (PARTITION BY model ORDER BY canvas_coverage, id) AS rn, COUNT(*) OVER (PARTITION BY model) AS n FROM c) SELECT model, n, id, DATE(started_at) AS d, total_steps, canvas_coverage, painting_title FROM r WHERE rn = CEIL(n / 2) ORDER BY model;
